using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.Rendering;
using UnityEngine.UIElements;
namespace MassiveArmy.Planetary
{
    [DefaultExecutionOrder(-220)]public sealed class PlanetHqTerrainValidation:MonoBehaviour
    {
        [Serializable]sealed class Report{public string status="PASS",error="";public List<string> checks=new List<string>();public float minimumHeight,maximumHeight,gpuHeightError,mountainCameraDistance,stampSeamError,cornerCacheError;public int mountains,plains,ocean,routeSamples,terrainPixels,cacheRebuilds,cacheMissReason;public float[] armyExitDistance=new float[2];}
        readonly Report report=new Report();PlanetDevelopment world;string output;RenderTexture target,ui,composite;Material compositeMaterial;
        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(!Application.isEditor&&Array.IndexOf(Environment.GetCommandLineArgs(),"-planet-hq-terrain-validation")>=0)new GameObject("HQ and mainland terrain validation").AddComponent<PlanetHqTerrainValidation>();}
        void Awake(){var args=Environment.GetCommandLineArgs();output=args[Array.IndexOf(args,"-planet-output")+1];Directory.CreateDirectory(output);world=FindAnyObjectByType<PlanetDevelopment>();world.currentRtsContent=true;world.sessionMode=PlanetGameMode.AiTest;world.configuredRadius=120000;world.requestedCapacity=8192;world.ambientZombies=0;Application.targetFrameRate=-1;QualitySettings.vSyncCount=0;}
        void Start(){StartCoroutine(Guard());}
        void Check(bool valid,string text){if(!valid)throw new InvalidOperationException(text);report.checks.Add(text);}
        IEnumerator Guard(){var run=Run();while(true){object next;try{if(!run.MoveNext())break;next=run.Current;}catch(Exception e){report.status="FAIL";report.error=e.ToString();Debug.LogException(e);break;}yield return next;}File.WriteAllText(Path.Combine(output,"validation.json"),JsonUtility.ToJson(report,true));Time.captureDeltaTime=0;Application.Quit(report.status=="PASS"?0:1);}
        void Capture(string name){RenderPipeline.SubmitRenderRequest(world.View,new RenderPipeline.StandardRequest{destination=target});compositeMaterial.SetTexture("_Ui",ui);Graphics.Blit(target,composite,compositeMaterial);var old=RenderTexture.active;RenderTexture.active=target;var raw=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);raw.ReadPixels(new Rect(0,0,target.width,target.height),0,0);raw.Apply();int visible=raw.GetPixels32().Count(c=>c.r>20||c.g>20||c.b>20);Destroy(raw);if(name=="ai-mainland-and-hq"){report.terrainPixels=visible;Check(visible>target.width*target.height/8,"Actual mainland terrain renders visible pixels beneath the HQ HUD");}RenderTexture.active=composite;var image=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();File.WriteAllBytes(Path.Combine(output,name+".png"),image.EncodeToPNG());Destroy(image);RenderTexture.active=old;}
        IEnumerator Run(){while(!world.Ready||world.HeadquartersForValidation==null)yield return null;world.Paused=true;world.Rig.InputEnabled=false;Check(world.StrategyEnabled&&world.definition.radius==120000,"The real AI Test session retains the 120 km-radius planet and both autonomous factions");
            Check(PlanetStampLibrary.Shared.Count==12&&world.definition.stampTerrain,"The gameplay planet uses twelve imported Unity height stamps");
            float first=PlanetStampLibrary.Shared.Height(new Vector3(.3f,.7f,.2f).normalized,73129);for(int i=0;i<64;i++)PlanetStampLibrary.Shared.Height(new Vector3(i+1,2,3).normalized,42+i);
            Check(first==PlanetStampLibrary.Shared.Height(new Vector3(.3f,.7f,.2f).normalized,73129),"Stamp placement and rotation are deterministic regardless of traversal order or other seeds");
            Check(Mathf.Abs(first-PlanetStampLibrary.Shared.Height(new Vector3(.3f,.7f,.2f).normalized,73130))>.00001f,"Changing the planet seed changes its stamp composition");
            for(int face=0;face<6;face++)for(int edge=0;edge<4;edge++)for(int j=0;j<=32;j++){float t=-1+j/16f;var uv=edge<2?new Vector2(edge==0?-1:1,t):new Vector2(t,edge==2?-1:1);var axis=CubeSphere.Normal[face]+CubeSphere.Right[face]*uv.x+CubeSphere.Up[face]*uv.y;var perpendicular=edge<2?CubeSphere.Right[face]:CubeSphere.Up[face];float a=PlanetTerrainEdits.BaseHeight(world.definition,(axis+perpendicular*.0000005f).normalized),b=PlanetTerrainEdits.BaseHeight(world.definition,(axis-perpendicular*.0000005f).normalized);report.stampSeamError=Mathf.Max(report.stampSeamError,Mathf.Abs(a-b));}
            Check(report.stampSeamError<.2f,"All cube-face edges and corners remain continuous with deterministic spherical stamps");
            double maskSum=0,mask2=0,waveSum=0,wave2=0,product=0;const int bandSamples=4096;
            for(int i=0;i<bandSamples;i++){float y=1-2*(i+.5f)/bandSamples,a=i*2.39996323f,r=Mathf.Sqrt(1-y*y);var d=new Vector3(r*Mathf.Cos(a),y,r*Mathf.Sin(a));double mask=PlanetTerrainEdits.MountainWeight(world.definition,d),wave=Mathf.Sin(Vector3.Dot(d,new Vector3(19,13,17))+(world.definition.terrainSeed%1009)*.017f);maskSum+=mask;mask2+=mask*mask;waveSum+=wave;wave2+=wave*wave;product+=mask*wave;}
            double correlation=Math.Abs((product-maskSum*waveSum/bandSamples)/Math.Sqrt((mask2-maskSum*maskSum/bandSamples)*(wave2-waveSum*waveSum/bandSamples)));
            Check(correlation<.4,"Mountain placement no longer follows the previous parallel sine bands (correlation "+correlation.ToString("F4")+")");
            var surface=new PlanetSurface(world.definition);var directions=new Vector4[8192];report.minimumHeight=float.MaxValue;report.maximumHeight=float.MinValue;Vector3 mountain=Vector3.up;float litMountainHeight=float.MinValue;
            for(int i=0;i<directions.Length;i++){float y=1-2*(i+.5f)/directions.Length,a=i*2.39996323f,r=Mathf.Sqrt(1-y*y);var d=new Vector3(r*Mathf.Cos(a),y,r*Mathf.Sin(a));directions[i]=new Vector4(d.x,d.y,d.z,0);float h=surface.SampleHeight(d);report.minimumHeight=Mathf.Min(report.minimumHeight,h);if(h>report.maximumHeight){report.maximumHeight=h;}if(h>litMountainHeight&&Vector3.Dot(d,world.Base.Homes[0])>.7f){litMountainHeight=h;mountain=d;}if(h<world.definition.oceanHeight)report.ocean++;if(h>500)report.mountains++;
                if(h>world.definition.oceanHeight+60&&PlanetTerrainEdits.MountainWeight(world.definition,d)<.02f){var east=Vector3.Cross(Vector3.up,d).normalized;float change=Mathf.Abs(surface.SampleHeight((d+east*(200/world.definition.radius)).normalized)-h);if(change<15)report.plains++;}}
            for(int i=0;i<directions.Length;i++){var d=((Vector3)directions[i]).normalized;report.cornerCacheError=Mathf.Max(report.cornerCacheError,Mathf.Abs(PlanetStampLibrary.Shared.Height(d,world.definition)-PlanetStampLibrary.Shared.Height(d,world.definition.terrainSeed))*world.definition.terrainHeight);}
            Check(report.cornerCacheError<.001f,"Cached stamp descriptors reproduce the uncached seeded reference without changing terrain shapes");
            Check(report.maximumHeight-report.minimumHeight>1400&&report.mountains>100,"Global terrain contains substantial mountain ranges and deep lowlands");Check(report.plains>300&&report.ocean>1000,"Natural broad plains and oceans coexist with mountains");
            var gpu=Instantiate(Resources.Load<ComputeShader>("MassiveArmy/PlanetTerrainValidation"));using(var input=new GraphicsBuffer(GraphicsBuffer.Target.Structured,directions.Length,16))using(var result=new GraphicsBuffer(GraphicsBuffer.Target.Structured,directions.Length,16)){input.SetData(directions);PlanetDevelopment.BindSurface(gpu,world.definition);gpu.SetInt("_SampleCount",directions.Length);gpu.SetBuffer(0,"_Directions",input);gpu.SetBuffer(0,"_Samples",result);gpu.Dispatch(0,(directions.Length+127)/128,1,1);var samples=new Vector4[directions.Length];result.GetData(samples);for(int i=0;i<samples.Length;i++)report.gpuHeightError=Mathf.Max(report.gpuHeightError,Mathf.Abs(samples[i].x-surface.SampleHeight(directions[i])));}Destroy(gpu);Check(report.gpuHeightError<.2f,"CPU collision/base placement and GPU terrain/navigation agree on the new terrain heights");
            Check(world.Base.Buildings.Count(b=>b.definition.id=="command"&&!b.removed)==2,"Both team headquarters spawn on separate natural mainland starting areas");
            Check(Vector3.Angle(world.Base.Homes[0],world.Base.Homes[1])>=149,"AI factions begin on opposite sides of the planet");
            foreach(var home in world.Base.Homes){var eastHome=Vector3.Cross(Mathf.Abs(home.y)>.95f?Vector3.right:Vector3.up,home).normalized;var northHome=Vector3.Cross(home,eastHome);
                for(int x=-1500;x<=1500;x+=250)for(int z=-1500;z<=1500;z+=250){var d=(home+(eastHome*x+northHome*z)/world.definition.radius).normalized;report.routeSamples++;Check(PlanetTerrainEdits.BaseHeight(world.definition,d)>world.definition.oceanHeight+15,"Both starting areas have naturally dry expansion land before terraforming");}}
            Check(report.routeSamples>300,"Both AI bases have independently sampled dry expansion regions");
            foreach(int seed in new[]{1,42,999,73129,73130,123456,987654,17}){var definition=ScriptableObject.CreateInstance<PlanetDefinition>();definition.radius=120000;definition.stampTerrain=true;definition.terrainHeight=1800;definition.oceanHeight=-35;definition.terrainSeed=seed;var selected=PlanetStartingRegion.Select(definition,new Vector3(1,.12f,1.3f));var east=Vector3.Cross(Vector3.up,selected).normalized;bool dry=true;for(int step=0;step<=72;step++){var d=(selected+east*((step*100-1000)/definition.radius)).normalized;dry&=PlanetTerrainEdits.BaseHeight(definition,d)>definition.oceanHeight+15;}Check(dry,"Seed "+seed+" selects naturally connected land without manufacturing islands");Vector3 opposite=Vector3.zero;
                foreach(var candidate in PlanetStartingRegion.OppositeCandidates(definition,selected))if(PlanetStartingRegion.ExpansionPlain(definition,candidate)){opposite=candidate;break;}
                Check(opposite.sqrMagnitude>.99f&&Vector3.Angle(selected,opposite)>=149,"Seed "+seed+" also has a naturally dry opposing mainland");Destroy(definition);}
            target=new RenderTexture(1600,1000,24,RenderTextureFormat.ARGBHalf);target.Create();ui=new RenderTexture(1600,1000,0,RenderTextureFormat.ARGB32);ui.Create();composite=new RenderTexture(1600,1000,0,RenderTextureFormat.ARGB32);composite.Create();compositeMaterial=new Material(Resources.Load<Shader>("MassiveArmy/PlanetUiComposite"));world.View.enabled=false;world.View.targetTexture=target;world.Hud.SetRenderTarget(ui);
            for(int i=0;i<6;i++)yield return null;Check(world.Hud.Root.Q<Label>("team-0-hq-marker")!=null&&world.Hud.Root.Q<Label>("team-1-hq-marker")!=null,"Shared original game UI contains both team HQ marker labels");Check(world.HeadquartersForValidation.States.All(s=>s.visible&&s.distance>0),"Both living HQs have visible distance markers in AI Test");Capture("ai-mainland-and-hq");
            yield return new WaitForSecondsRealtime(.3f);int retained=world.HeadquartersForValidation.GeometryRebuilds;for(int i=0;i<15;i++)yield return null;report.cacheRebuilds=world.HeadquartersForValidation.GeometryRebuilds-retained;report.cacheMissReason=world.HeadquartersForValidation.CacheMissReason;Check(report.cacheRebuilds<=1,"A stationary HQ overlay retains its vector geometry instead of repainting the shared game UI every frame");
            world.FocusFaction(0);world.Rig.RefreshPose();for(int i=0;i<3;i++)yield return null;Check(world.HeadquartersForValidation.States[1].edge,"The other team's offscreen HQ receives an edge bearing");Capture("hq-offscreen-bearing");
            Check(PlanetHeadquartersHud.BehindHorizon(new Double3(0,121000,0),new Double3(0,-120035,0),120000),"A far-side HQ is identified as beyond the planetary horizon");Check(!PlanetHeadquartersHud.BehindHorizon(new Double3(0,121000,0),new Double3(0,120035,0),120000),"A near-side HQ is not falsely hidden by the planetary horizon");
            world.SetShipControl(true);for(int i=0;i<3;i++)yield return null;Check(world.IsPiloting&&world.HeadquartersForValidation.States.All(s=>s.visible),"HQ markers remain available in the pilot seat");world.SetFirstPerson(true);for(int i=0;i<3;i++)yield return null;Check(world.IsFirstPerson&&world.HeadquartersForValidation.States.All(s=>s.visible),"HQ markers remain available while walking");world.SetFirstPerson(false);
            world.Rig.SetFocusDirection(mountain);world.Rig.Distance=7000;world.Rig.RefreshPose();var front=world.Hud.Root.Q("front");front.style.display=DisplayStyle.None;yield return new WaitForSecondsRealtime(.3f);report.mountainCameraDistance=(float)(world.RenderToBody(Vector3.zero)-surface.GetSurfacePositionPrecise(mountain)).Magnitude;Check(Mathf.Abs(report.mountainCameraDistance-7000)<1,"Mountain capture uses the actual mountain viewpoint");Capture("mountain-relief");front.style.display=DisplayStyle.Flex;world.Rig.SetFocusDirection(world.Base.Homes[0]);world.Rig.Distance=650;world.Rig.RefreshPose();
            // Use the actual AI and GPU army for an accelerated departure test, with no replacement unit simulation.
            Time.captureDeltaTime=.1f;world.Paused=false;foreach(int faction in new[]{0,1}){world.FocusFaction(faction);world.Rig.RefreshPose();uint until=world.SimulationTicks+2100;while(world.SimulationTicks<until)yield return null;}world.Paused=true;var units=new UnitState[world.unitCount];world.UnitsForValidation.GetData(units);
            for(int team=0;team<2;team++){foreach(var unit in units){if((unit.flags&1)==0||(unit.packed&255)!=team)continue;var movement=world.Base.Catalog.units[(unit.packed>>8)&255].movement;if(movement==MovementClass.Air||movement==MovementClass.Water)continue;float distance=CubeSphere.ArcDistance(CubeSphere.Decode(unit.position),world.Base.Homes[team],world.definition.radius);report.armyExitDistance[team]=Mathf.Max(report.armyExitDistance[team],distance);}Check(report.armyExitDistance[team]>700,"Faction "+(team+1)+" ground troops leave the starting plateau using the original GPU AI movement");}
            Check(world.Base.AIDecisions.All(n=>n>10),"Both factions continue autonomous base decisions while troops can leave");Check(world.View.transform.position==Vector3.zero,"HQ tracking and terrain changes retain the camera-at-zero floating origin");Capture("ai-mainland-armies");
            var command=world.Base.Buildings.First(b=>b.team==1&&b.definition.id=="command");world.Base.Damage(command,1000000);world.HeadquartersForValidation.Tick();Check(!world.HeadquartersForValidation.States[1].visible,"Destroyed headquarters lose their HUD marker");
        }
        void OnDestroy(){Time.captureDeltaTime=0;world?.Hud?.SetRenderTarget(null);foreach(var rt in new[]{target,ui,composite})if(rt!=null){rt.Release();Destroy(rt);}if(compositeMaterial!=null)Destroy(compositeMaterial);}
    }
}
